(function(){'use strict';const bank=window.PCPE_QUESTOES_AGENTE;function add(d,p,rows){const offset=bank[d].filter(q=>q.id.startsWith(p)).length;rows.forEach(([topic,text,a,w,exp],i)=>{const correct=(offset+i)%5,options=w.slice();options.splice(correct,0,a);bank[d].push({id:p+String(offset+i+1).padStart(3,'0'),topic,text,options,correct,exp:exp+" As demais alternativas confundem institutos, ampliam ou restringem indevidamente o alcance da regra, ou acrescentam exceções e requisitos sem amparo no texto aplicável."});});}
add('Legislação Estadual','AG-Q1-EST-',[
['CE-PE: dever de segurança','Em reunião de planejamento, gestor afirma que segurança pública é atribuição exclusiva do Estado e que a coletividade não tem responsabilidade. Assinale a opção correta.','A segurança pública é dever do Estado, direito e responsabilidade de todos, voltada à ordem pública e à incolumidade das pessoas e do patrimônio.',['É dever exclusivo dos municípios.','Protege somente o patrimônio público.','É dever apenas dos agentes policiais.','Autoriza afastar genericamente garantias individuais.'],'A Constituição reúne dever estatal, direito e responsabilidade de todos e objetivos de proteção da ordem, das pessoas e dos bens. Não restringe a incumbência a municípios nem suspende garantias.'],
['CE-PE: hierarquia normativa','Lei estadual pretende contrariar norma constitucional federal sobre segurança pública. Um gestor alega que a autonomia estadual torna isso válido. Assinale a opção correta.','A autonomia estadual deve ser exercida nos limites da Constituição Federal; lei estadual não pode contrariá-la.',['A lei estadual prevalece sempre por ser mais específica.','A Constituição Federal vincula apenas órgãos federais.','A Constituição estadual pode afastar direitos fundamentais federais.','Decreto pode revogar disposição constitucional.'],'A Constituição Federal ocupa posição superior e vincula os estados. Autonomia não é soberania; lei, decreto ou rotina não afastam parâmetro constitucional.'],
['CE-PE: atribuição da Polícia Civil','Em investigação de delito comum, servidor afirma que a Polícia Civil só atua após oferecida a denúncia. Assinale a opção correta.','A Polícia Civil exerce funções de polícia judiciária e apura infrações penais, ressalvadas as militares, nos termos constitucionais.',['Exerce exclusivamente policiamento ostensivo.','Só atua por delegação judicial após a ação penal.','Executa penas, mas não investiga.','Apura toda infração militar em qualquer hipótese.'],'A investigação de crimes comuns e a polícia judiciária integram a missão da Polícia Civil. O policiamento ostensivo cabe à PM; a investigação não depende do oferecimento de denúncia.'],
['CE-PE: requisitos de direção','Uma alternativa afirma que a chefia da Polícia Civil pode ser entregue a qualquer particular, sem observar a Constituição estadual. Assinale a opção correta.','A direção e organização da Polícia Civil devem observar os requisitos da Constituição estadual e da legislação regulamentadora.',['A chefia é exercida pelo presidente do Tribunal de Justiça.','A função é eletiva por voto popular.','A Constituição proíbe regras estaduais sobre a direção.','A contratação privada dispensa requisitos legais.'],'A direção institucional está sujeita à Constituição e à lei. Eleição, terceirização ou autoridade inventada não substituem os requisitos normativos; conferir redação vigente da CE-PE.'],
['CE-PE: infrações militares','Na triagem de ocorrência, a equipe deve distinguir apuração de delito comum da infração penal militar. Assinale a opção correta.','A atribuição de apuração da Polícia Civil não abrange infrações penais militares, sujeitas à competência constitucional própria.',['A Polícia Civil apura toda infração militar.','A condição civil do suspeito transforma qualquer delito em comum.','A distinção entre delito comum e militar é irrelevante.','A PM nunca exerce polícia judiciária.'],'A Constituição ressalva as infrações militares da atribuição da Polícia Civil. A natureza do delito e as regras de competência importam; não se presume a atribuição apenas pela pessoa investigada.'],
['CE-PE: cooperação institucional','Órgãos de segurança coordenam resposta a ocorrência. Um agente diz que integração extingue as competências próprias de cada instituição. Assinale a opção correta.','A cooperação pode ocorrer sem apagar as atribuições e limites constitucionais de cada órgão.',['Integração transfere toda investigação à PM.','A Constituição fica suspensa durante operação conjunta.','Atuação integrada elimina controle judicial.','Cooperação exige extinguir os órgãos envolvidos.'],'Coordenação é compatível com competências legais próprias; não implica transferência automática, suspensão constitucional, imunidade a controle ou extinção institucional.'],
['CE-PE: garantias individuais','Em investigação grave, agente propõe afastar direitos fundamentais sem lei ou controle. Assinale a opção correta.','A atuação de segurança pública continua submetida à Constituição, às leis e às garantias fundamentais.',['Gravidade substitui base legal.','Sigilo suspende todas as garantias.','O agente escolhe livremente qualquer restrição.','As garantias só incidem após o inquérito.'],'Investigação não cria zona livre de Constituição. Restrição exige fundamento jurídico e, quando cabível, autorização competente; sigilo não suspende direitos.'],
['CE-PE: finalidade','Um relatório descreve segurança pública como proteção exclusiva de prédios governamentais. Assinale a opção correta.','A finalidade constitucional abrange ordem pública, incolumidade das pessoas e do patrimônio e asseguramento da liberdade e das garantias.',['Limita-se a repartições estaduais.','Protege só o patrimônio privado.','Liberdade é incompatível com segurança.','Ordem pública suprime garantias permanentemente.'],'O objeto constitucional é mais amplo do que edifícios: inclui ordem, pessoas, patrimônio, liberdade e garantias. Segurança não é autorização para suprimi-las.']
]);
add('Legislação Estadual','AG-Q1-EST-',[
['Polícia Civil e ostensividade','Em prova, candidato atribui à Polícia Civil o policiamento ostensivo como função típica exclusiva. Assinale a opção correta.','A Polícia Civil atua tipicamente na polícia judiciária e apuração; o policiamento ostensivo compete à Polícia Militar.',['Policiamento ostensivo é exclusivo da PC.','PC e PM têm atribuições idênticas.','PM investiga exclusivamente crimes comuns.','Nenhuma polícia estadual preserva a ordem.'],'A Constituição diferencia investigação da PC e policiamento ostensivo/preservação da ordem pela PM. As atribuições não são idênticas nem se excluem.'],
['Lei 6.425/1972: objeto','Servidora procura o diploma estadual que institui regime jurídico peculiar dos funcionários policiais civis ocupantes de cargos de atividade policial. Assinale a opção correta.','A Lei estadual nº 6.425/1972 é o Estatuto do Policial Civil e disciplina o regime peculiar indicado.',['A LC 137/2008 institui regime geral de todos servidores.','A Lei 6.123/1968 é o PCCV exclusivo da PCPE.','A LC 317/2015 institui regime geral estadual.','Não há estatuto policial estadual.'],'A Lei 6.425/1972 é o estatuto específico policial; a LC 137 trata do PCCV, a Lei 6.123 do estatuto geral e a LC 317 de regra específica dos Delegados. Conferir texto vigente.'],
['Lei 6.425/1972: limites','Policial invoca o estatuto peculiar para alegar que a Constituição não se aplica à sua relação funcional. Assinale a opção correta.','O regime específico permanece subordinado à Constituição e deve ser interpretado com normas gerais compatíveis.',['Lei especial afasta automaticamente a Constituição.','Policial civil deixa de ser agente público.','Estatuto revoga toda lei geral estadual.','Lei geral sempre prevalece, ainda que contrarie norma especial válida.'],'A norma especial não supera a Constituição; sua relação com normas gerais depende do âmbito e compatibilidade. Não há imunidade normativa. Conferir alterações vigentes.'],
['Lei 6.425/1972: atualização','Apostila antiga cita requisito funcional da Lei 6.425/1972, mas não informa atualização. Qual a providência segura?','Consultar versão consolidada oficial e alterações vigentes antes de afirmar requisito específico.',['A apostila prevalece sobre lei atual.','A lei de 1972 não pode ter sido alterada.','Regra revogada continua sempre válida.','Resumo dispensa consulta ao texto legal.'],'Legislação pode ser alterada e a versão vigente prevalece. Material de apoio não substitui fonte oficial; por isso não se deve afirmar requisito sem conferir sua redação atual.'],
['Lei 6.425/1972: garantias disciplinares','Gestor afirma que estatuto policial permite punir servidor sem defesa por causa da natureza do cargo. Assinale a opção correta.','Sanção administrativa deve respeitar devido processo, contraditório e ampla defesa, além da lei aplicável.',['A natureza policial elimina o contraditório.','Punição pode ser verbal em qualquer hipótese.','Constituição não alcança processo administrativo.','Defesa só existe em ação penal.'],'As garantias constitucionais também limitam a Administração sancionadora. O rito específico deve ser observado, mas não pode eliminar devido processo e defesa.'],
['Lei 6.123/1968: estatuto geral','Dois diplomas estaduais tratam de servidores: um regime geral e outro peculiar aos policiais civis. Assinale a opção correta.','A Lei nº 6.123/1968 é o Estatuto dos Funcionários Públicos Civis de Pernambuco, de alcance geral.',['É a Constituição estadual.','Institui somente o PCCV da PCPE.','Regulamenta só o cargo de Delegado.','É lei federal aplicável apenas à União.'],'A Lei 6.123/1968 é o estatuto geral estadual, distinto do regime peculiar da Lei 6.425/1972 e do PCCV da LC 137/2008. Conferir incidência concreta e redação vigente.'],
['Lei 6.123/1968: convivência normativa','Servidor pretende aplicar a Lei 6.123/1968 ignorando norma especial de sua carreira. Assinale a opção correta.','É necessário identificar o alcance de cada norma e compatibilizar o estatuto geral com as regras especiais válidas.',['Lei geral afasta sempre lei especial.','Norma especial prevalece mesmo se inconstitucional.','Estatuto geral torna desnecessária lei de carreira.','Administração escolhe livremente a regra.'],'A aplicação depende de âmbito, vigência, hierarquia e compatibilidade. Nem regra geral nem especial dispensa controle constitucional ou leitura sistemática.'],
['Lei 6.123/1968: direito intertemporal','A lei estadual anterior a 1988 é citada em questão atual. Candidato conclui que ela necessariamente perdeu vigência por ser antiga. Assinale a opção correta.','A antiguidade não basta para afastar a norma; deve-se verificar recepção, alterações e vigência atual.',['Toda lei pré-1988 é automaticamente inválida.','Lei antiga nunca pode ser alterada.','A lei federal de servidores substitui automaticamente o estatuto estadual.','A data de promulgação resolve sozinha a vigência.'],'Norma anterior pode ser recepcionada se compatível, mas também pode ter sido alterada ou revogada. É necessário verificar texto vigente; não se presume invalidade nem permanência irrestrita.']
]);add('Legislação Estadual','AG-Q1-EST-',[
['LC 137/2008: finalidade','Gestão busca norma que instituiu Plano de Cargos, Carreiras e Vencimentos dos servidores do quadro próprio da Polícia Civil pernambucana. Assinale a opção correta.','A LC estadual nº 137/2008 institui o PCCV no âmbito da Polícia Civil de Pernambuco.',['A Lei 6.123/1968 institui o PCCV policial.','A LC 317/2015 cria estatuto geral estadual.','A CF criou diretamente a tabela remuneratória da PCPE.','A Lei 6.425 extinguiu qualquer plano posterior.'],'A LC 137/2008 institui o PCCV da PCPE, objeto diferente do estatuto geral, estatuto policial e regra específica dos Delegados. Conferir texto consolidado e atos de regulamentação.'],
['LC 137/2008: destinatários','Servidor de outro órgão estadual reivindica automaticamente vantagem do PCCV da Polícia Civil por também ser servidor público. Assinale a opção correta.','A aplicação depende de enquadramento no âmbito subjetivo e funcional definido pela LC 137, não apenas de ser servidor estadual.',['Todo servidor estadual integra o quadro próprio da PCPE.','Qualquer lotação torna aplicável o PCCV policial.','O plano alcança indistintamente servidores municipais.','A lei não pode delimitar seus destinatários.'],'O PCCV tem âmbito institucional próprio; condição genérica de servidor não demonstra integração ao quadro da PCPE. Verificar categorias e redação vigente antes de concluir sobre direito individual.'],
['LC 137/2008: sistema jurídico','Candidato trata o PCCV como substituto integral da Constituição e dos estatutos de servidores. Assinale a opção correta.','O PCCV deve ser lido em conjunto com princípios constitucionais e com os estatutos e normas compatíveis pertinentes.',['Hierarquia e disciplina autorizam violar a Constituição.','PCCV substitui os arts. 37 a 41 da CF.','Plano afasta toda lei geral estadual.','Carreira é imune ao controle de legalidade.'],'Plano de carreira não substitui normas superiores nem outros diplomas aplicáveis. Regras específicas operam dentro dos princípios constitucionais; confira consolidação vigente.'],
['LC 137/2008: objeto distinto','Uma questão confunde LC 137/2008 com Lei 6.425/1972 e Lei 6.123/1968. Assinale a opção correta.','O PCCV da LC 137 e os estatutos das Leis 6.425 e 6.123 têm objetos relacionados, mas não idênticos.',['Os três diplomas são uma só lei.','A LC 137 é estatuto geral e a Lei 6.123 é PCCV.','A Lei 6.425 regula municípios.','A LC 137 revogou a Constituição estadual.'],'A LC 137 trata do PCCV da PCPE; 6.425 é estatuto policial específico e 6.123 estatuto geral. Revogações e efeitos devem ser conferidos no texto consolidado.'],
['LC 137/2008: vigência','Candidata usa apenas a edição original da LC 137/2008 para responder requisito atual de progressão. Assinale a opção correta.','Deve verificar alterações e regulamentação posteriores e consultar texto consolidado vigente.',['Texto original sempre prevalece.','Regulamento pode contrariar livremente a lei.','Lei complementar nunca recebe alterações.','Material impresso dispensa verificação de vigência.'],'Regras funcionais podem ser alteradas ou regulamentadas. Regulamento respeita a lei e texto original não prevalece sobre alteração válida; requisitos específicos exigem conferência oficial.'],
['LC 317/2015: objeto','Qual diploma regulamenta o § 5º do art. 103 da Constituição do Estado de Pernambuco sobre o cargo de Delegado? Assinale a opção correta.','A Lei Complementar estadual nº 317/2015 regulamenta esse dispositivo da CE-PE.',['Lei 6.123/1968.','LC 137/2008.','Lei 6.425/1972 é a Constituição estadual.','Lei federal sobre Polícia Federal.'],'A LC 317/2015 é a lei regulamentadora indicada; os outros diplomas cuidam de estatutos ou PCCV. Conferir a redação oficial vigente.'],
['LC 317/2015: natureza do cargo','Um parecer classifica as funções de polícia judiciária e apuração exercidas por Delegado como privadas e terceirizáveis. Assinale a opção correta.','A LC 317 qualifica o cargo e essas funções como de natureza jurídica e policial, essenciais e exclusivas de Estado.',['A lei classifica as funções como privadas.','A terceirização dispensa lei.','Toda atividade administrativa é função policial.','A norma exclui natureza jurídica do cargo.'],'A LC 317 traz a qualificação de funções essenciais e exclusivas de Estado, sem tornar toda atividade administrativa policial. Contratos não afastam a reserva legal.'],
['LC 317/2015: ingresso','Edital prevê ingresso de Delegado por indicação em classe intermediária, sem concurso. Assinale a opção correta.','A LC 317 prevê ingresso na faixa e classe iniciais mediante concurso público de provas e títulos e requisitos legais.',['Indicação política substitui concurso.','Ingresso ocorre na classe final sem seleção.','A lei exige só entrevista.','Aprovação dispensa todas as outras exigências.'],'A lei prevê concurso de provas e títulos e ingresso inicial, além de requisitos próprios. Indicação não substitui concurso e aprovação não dispensa exigências legais. Conferir regras transitórias vigentes.']
]);add('Legislação Estadual','AG-Q1-EST-',[
['LC 317/2015: formação','Alternativa sobre ingresso de Delegado afirma que a LC 317 dispensa bacharelado em Direito. Assinale a opção correta.','A lei prevê diploma de bacharel em Direito, além das demais exigências legais de ingresso.',['Exige somente ensino fundamental.','Proíbe formação jurídica.','Diploma pode ser substituído por indicação política.','A lei não estabelece escolaridade.'],'A LC 317 prevê bacharelado em Direito, concurso e demais requisitos. A questão não afirma que essa seja a única condição; conferir redação vigente e regras transitórias.'],
['LC 317/2015: experiência','Material de estudo diverge sobre experiência para ingresso de Delegado. Qual leitura é mais segura?','A LC 317 prevê tempo mínimo de atividade jurídica ou policial e regra transitória ligada a concursos iniciados antes de sua vigência; confira texto atualizado.',['Experiência nunca foi exigida.','Qualquer experiência substitui requisitos legais.','A regra é idêntica para concurso iniciado antes da lei.','A banca decide informalmente se exige experiência.'],'O diploma estabelece requisito temporal de atividade jurídica ou policial e dispõe sobre concursos iniciados antes de sua vigência. A aplicação temporal exige conferência da redação vigente.'],
['LC 317/2015: remoção','Delegado é removido por ato que não apresenta fundamento. Assinale a opção correta.','A LC 317 determina que a remoção se dê por ato devidamente fundamentado.',['A remoção é sempre imotivada.','A lei veda toda remoção.','A remoção exige lei individual.','Motivação só cabe em processo penal.'],'A lei exige ato fundamentado; isso não significa proibição absoluta de remover ou autorização legislativa individual. Deve-se examinar motivação e texto vigente.'],
['LC 317/2015: imparcialidade','Delegado recebe ordem para formar convencimento sem isenção nem fundamentação. Assinale a opção correta.','A lei assegura interpretação do ordenamento com isenção, imparcialidade e de modo fundamentado no exercício das atribuições.',['Determina interpretação parcial.','Ordem informal prevalece sobre a lei.','Isenção impede aplicar a lei.','Autonomia autoriza ignorar direitos fundamentais.'],'A LC 317 assegura isenção, imparcialidade e fundamentação; não autoriza descumprir Constituição ou lei e não dispensa motivação.'],
['CE-PE: consulta ao texto consolidado','Candidato decora numeração de artigos da Constituição estadual sem verificar emendas. Assinale a opção correta.','Deve consultar a redação vigente dos dispositivos indicados no edital, inclusive alterações constitucionais posteriores.',['Emenda estadual não altera conteúdo.','Memorizar número dispensa conhecer texto.','Texto original é necessariamente vigente.','Toda regra estadual deve ser substituída pela federal.'],'Emendas podem modificar texto constitucional. A leitura atualizada evita atribuir conteúdo antigo a dispositivo; não se presume qual alteração ocorreu.'],
['Legislação estadual: legalidade','Superior ordena ato incompatível com a Constituição e invoca hierarquia funcional. Assinale a opção correta.','Hierarquia não dispensa legalidade nem valida ordem incompatível com normas superiores.',['Qualquer ordem superior é válida.','Legalidade só vincula o Judiciário.','Ordem revoga automaticamente lei.','Agente escolhe se aplica Constituição.'],'A hierarquia organiza relações de serviço, mas permanece subordinada à Constituição e à legalidade. Ordem incompatível não torna válida conduta arbitrária.'],
['Legislação estadual: aplicação temporal','Uma alteração legal entra em vigor após publicação do edital, sem regra específica no enunciado. Assinale a opção correta para análise.','É preciso verificar vigência, regras transitórias e delimitação do edital, sem presumir retroatividade ou aplicação automática de versão antiga.',['Toda alteração retroage.','A lei antiga rege qualquer prova futura.','Lei nunca produz efeitos antes de decisão judicial.','Edital torna a vigência irrelevante.'],'Aplicação temporal depende de vigência, transição e conteúdo do edital. Não se presume retroatividade nem se ignora norma vigente; conferir a regra aplicável.'],
['Normas estaduais: objetos','Um estudante trata 6.123/1968, 6.425/1972, LC 137/2008 e LC 317/2015 como diplomas intercambiáveis. Assinale a opção correta.','Deve distinguir estatuto geral, estatuto policial, PCCV da PCPE e regulamentação específica sobre Delegado.',['Todos tratam exclusivamente de remuneração.','Os diplomas têm objeto idêntico.','LC 317 substitui a Constituição estadual.','A Lei 6.123 rege apenas municípios.'],'Os diplomas possuem objetos distintos, embora possam se relacionar: regime geral civil, regime policial peculiar, PCCV e disciplina do cargo de Delegado. Conferir os textos vigentes.']
]);add('Legislação Estadual','AG-Q1-EST-',[
['CE-PE e CF: compatibilidade','Lei pernambucana pretende alterar competência constitucional federal de órgão policial. Assinale a opção correta.','A organização estadual deve respeitar o modelo, as competências e os limites constitucionais federais.',['Autonomia estadual permite contrariar a CF.','A CF não disciplina segurança pública.','Posterioridade da lei supera a Constituição.','A CE-PE afasta supremacia federal.'],'A autonomia estadual se exerce nos limites da Constituição Federal, que estabelece o modelo de segurança pública. Lei posterior não supera hierarquia constitucional.'],
['PCPE: controle de diligências','Equipe afirma que diligência investigativa é imune a controle judicial e garantias. Assinale a opção correta.','A investigação continua sujeita a controles e garantias constitucionais e processuais, inclusive reserva de jurisdição quando cabível.',['Toda diligência é imune a controle.','Garantias só surgem após condenação.','Delegado substitui juiz em qualquer decisão.','Investigação autoriza restrição sem lei.'],'A atividade investigativa não cria imunidade. Medida sujeita à reserva judicial exige autorização; todas as diligências devem respeitar lei e direitos fundamentais.'],
['Princípios da administração policial','Servidor diz que princípios do art. 37 não se aplicam à Polícia Civil por atuar na segurança pública. Assinale a opção correta.','A atividade policial permanece vinculada aos princípios constitucionais da administração pública.',['Função policial suspende impessoalidade.','Princípios só valem para empresas privadas.','Segurança é exceção integral ao art. 37.','Agente pode atuar por preferência pessoal.'],'A natureza da função não afasta legalidade, impessoalidade, moralidade, publicidade e eficiência, nem o controle público.'],
['Estatuto e defesa','Servidor sofre sanção sem procedimento, com alegação de que hierarquia substitui defesa. Assinale a opção correta.','Poder disciplinar sujeita-se à legalidade e às garantias de devido processo, contraditório e ampla defesa.',['Hierarquia elimina garantias.','Sanção verbal é sempre suficiente.','Processo interno não admite defesa.','Ato disciplinar não pode ser revisto.'],'A Administração deve observar limites legais e constitucionais, assegurando garantias processuais. A hierarquia não valida punição arbitrária.'],
['PCCV e reserva legal','Circular altera requisito de ingresso em carreira da PCPE definido em lei. Assinale a opção correta.','Ato infralegal pode regulamentar a lei, mas não modificar requisito legal nem contrariá-la.',['Circular prevalece se posterior.','Administração altera requisito sem lei.','Ingresso público não se submete à reserva legal.','Edital pode contrariar lei por conveniência.'],'Editais e atos internos submetem-se à lei. Regulamentar não é inovar contra texto legal; requisitos de ingresso devem observar reserva normativa.'],
['Legislação pernambucana: edital','Edital exige legislação de Pernambuco, mas candidato usa norma semelhante de outro estado. Assinale a opção correta.','Deve-se aplicar o direito estadual pernambucano indicado, não importar automaticamente regra de outro ente.',['Normas estaduais são intercambiáveis.','Numeração igual torna norma idêntica.','Lei federal substitui toda norma estadual de pessoal.','Silêncio autoriza presumir conteúdo local.'],'A questão delimita legislação de Pernambuco. Normas de outros entes não se aplicam por analogia automática; consulte os diplomas locais e o texto vigente.'],
['CE-PE: dever e direito','Cidadão conclui que a responsabilidade de todos elimina o dever do Estado na segurança pública. Assinale a opção correta.','A responsabilidade coletiva coexiste com o dever estatal constitucional de segurança pública.',['Participação social substitui o Estado.','Dever estatal pertence somente aos municípios.','Cidadãos recebem automaticamente poderes coercitivos.','A Constituição exclui a colaboração comunitária.'],'A fórmula constitucional combina dever estatal com direito e responsabilidade de todos. Participação não transfere poderes policiais nem extingue obrigações públicas.'],
['CE-PE: leitura dos arts. 101–105-B','Estudante responde questão estadual atribuindo a artigo específico conteúdo que não conferiu em fonte oficial. Assinale a opção correta.','Deve consultar a redação vigente dos dispositivos do edital e evitar atribuir números ou regras sem confirmação.',['Artigos estaduais nunca são emendados.','Resumo não oficial prevalece sobre texto consolidado.','Qualquer artigo pode ser presumido por analogia.','Conferência é dispensável para lei estadual.'],'O recorte dos arts. 101 a 105-B exige atenção à redação atual e às emendas. Sem confirmação, não se deve inventar conteúdo ou numeração; consulte fonte oficial.']
]);add('Noções de Direito Constitucional','AG-Q1-CON-',[
['Fundamentos da República','Aluno inclui separação de Poderes entre os fundamentos do art. 1º. Assinale a opção correta.','A dignidade da pessoa humana é fundamento; a separação de Poderes está prevista em outro dispositivo constitucional.',['Dignidade é objetivo do art. 3º.','Separação de Poderes é fundamento expresso do art. 1º.','Soberania não é fundamento.','Pluralismo é direito social, não fundamento.'],'O art. 1º enumera soberania, cidadania, dignidade, valores sociais do trabalho e livre iniciativa e pluralismo. Separação de Poderes aparece no art. 2º.'],
['Objetivos fundamentais','Política pública busca reduzir desigualdades sociais e regionais. Parecer chama isso de fundamento da República. Assinale a opção correta.','Reduzir desigualdades é objetivo fundamental previsto no art. 3º.',['É fundamento do art. 1º.','É competência exclusiva municipal.','Autoriza discriminação arbitrária.','É incompatível com sociedade livre e justa.'],'O art. 3º trata de objetivos fundamentais, entre eles reduzir desigualdades. Fundamentos estão no art. 1º; igualdade material não autoriza arbitrariedade.'],
['Relações internacionais','Candidata classifica a prevalência dos direitos humanos como fundamento interno do Estado. Assinale a opção correta.','A prevalência dos direitos humanos rege as relações internacionais da República.',['É apenas objetivo do art. 3º.','É princípio das relações internacionais.','É fundamento da autonomia municipal.','Não há princípios constitucionais internacionais.'],'A Constituição coloca prevalência dos direitos humanos entre princípios que regem as relações internacionais; não integra o rol de fundamentos do art. 1º.'],
['Poder constituinte originário','Nova ordem constitucional é inaugurada após ruptura da ordem anterior. Assinale a opção correta sobre o poder constituinte originário.','É inicial e não deriva juridicamente da Constituição anterior.',['É derivado e segue rito de emenda anterior.','É exercido exclusivamente pelo STF.','É limitado por cláusula pétrea do texto substituído.','É competência administrativa ordinária.'],'O poder originário inaugura nova ordem e não deriva do texto anterior; não se confunde com emenda, jurisdição ou poder regulamentar.'],
['Poder constituinte reformador','Proposta de emenda tramita conforme o rito constitucional. Assinale a opção correta.','O poder reformador é instituído e limitado pela Constituição vigente, inclusive por limites formais e materiais.',['É inicial e ilimitado.','Pode abolir cláusula pétrea por maioria simples.','É exercido por decreto presidencial.','Não possui limites materiais.'],'O poder reformador decorre da Constituição e observa procedimento e limites, inclusive cláusulas pétreas; não é originário nem se exerce por decreto.'],
['Poder constituinte decorrente','Estado organiza sua própria Constituição. Assinale a opção correta.','A auto-organização estadual deve respeitar princípios e limites da Constituição Federal.',['Constituição estadual pode contrariar livremente a federal.','Estado possui soberania internacional.','Estado não pode elaborar Constituição própria.','Constituição estadual é superior à federal.'],'O poder decorrente permite autonomia estadual subordinada à Constituição Federal. Estados não são soberanos e não podem inverter hierarquia normativa.'],
['Cláusulas pétreas','PEC pretende abolir a forma federativa de Estado. Assinale a opção correta.','A forma federativa é protegida contra deliberação de proposta tendente à sua abolição.',['Aprovação simples em uma Casa basta.','Cláusula pétrea limita somente leis ordinárias.','Plebiscito afasta qualquer limite.','Vedação protege apenas redação literal.'],'O art. 60, §4º, impede até a deliberação de proposta tendente a abolir a Federação. Maioria ou plebiscito não elimina esse limite material.'],
['Mutação constitucional','Interpretação de dispositivo evolui sem alteração formal do texto. Assinale a opção correta.','Pode haver mutação constitucional, desde que a interpretação permaneça compatível com o texto e a ordem constitucional.',['Toda interpretação nova é emenda formal.','Mutação permite ignorar o texto.','Só o poder originário interpreta a Constituição.','A mutação extingue o dispositivo escrito.'],'Mutação altera o sentido por interpretação ou prática, sem mudar o texto. Não autoriza contrariar texto constitucional nem substitui procedimento de emenda.']
]);add('Noções de Direito Constitucional','AG-Q1-CON-',[
['Eficácia plena','Norma constitucional dispõe de todos os elementos para produzir efeitos essenciais desde a promulgação, sem lei integradora. Assinale a opção correta.','É norma de eficácia plena, sem prejuízo de regulamentação compatível.',['É limitada e sem efeito imediato.','É contida e depende sempre de lei.','É programática sem força vinculante.','É norma não escrita.'],'Eficácia plena significa aptidão imediata e integral para efeitos essenciais; regulamentação compatível ainda pode existir, mas integração não é condição de eficácia.'],
['Eficácia contida','Norma assegura direito imediatamente, admitindo restrição por lei nos limites constitucionais. Assinale a classificação correta.','É norma de eficácia contida, imediatamente aplicável e passível de restrição válida.',['É limitada e sem efeito antes de lei.','Não produz efeito jurídico.','Só vale após emenda.','É plena e nunca admite restrição.'],'Norma contida tem aplicabilidade imediata e pode sofrer restrição autorizada. Diferencia-se da limitada, cuja aplicação plena depende de integração.'],
['Eficácia limitada','Norma prevê instituição a ser criada por lei e não contém elementos para completa implementação. Assinale a opção correta.','A eficácia integral pode depender de regulamentação, mas a norma conserva efeitos mínimos e força vinculante.',['É inexistente até ser copiada em lei.','Falta de regulamentação elimina qualquer obrigação.','É plena e dispensa qualquer medida.','É simples recomendação sem valor jurídico.'],'Norma limitada depende de integração para plenitude, mas vincula legislador e pode ter efeitos mínimos. Não é inexistente nem facultativa.'],
['Aplicabilidade de direitos fundamentais','Autoridade afirma que direitos fundamentais só vinculam após lei específica. Assinale a opção correta.','Normas definidoras de direitos e garantias fundamentais têm aplicação imediata, sem afastar regulamentação necessária.',['Dependem sempre de lei complementar.','Vinculam somente o Judiciário.','Aplicação imediata torna toda regulamentação proibida.','Legislador não pode concretizar direitos.'],'A Constituição determina aplicação imediata. Isso não significa que toda norma dispense concretização nem impede regulamentação legislativa.'],
['Princípio da igualdade','Órgão cria distinção sem base razoável entre candidatos em situação equivalente. Assinale a opção correta.','Isonomia veda discriminações arbitrárias, embora admita distinções justificadas e constitucionais.',['Igualdade proíbe toda diferenciação.','Preferência pessoal justifica distinção.','Isonomia só vale entre particulares.','Edital pode autorizar discriminação arbitrária.'],'Igualdade exige tratamento isonômico e não impede diferenciação justificável e proporcional. Edital não legitima discriminação incompatível com a Constituição.'],
['Legalidade individual','Cidadão é obrigado a agir sem que lei ou Constituição imponha tal dever. Assinale a opção correta.','Ninguém será obrigado a fazer ou deixar de fazer algo senão em virtude de lei.',['Legalidade protege só agentes públicos.','Administração cria dever por rotina interna.','Cidadão só age com autorização estatal.','Ausência de lei permite obrigação arbitrária.'],'A legalidade constitucional protege o particular contra dever imposto sem lei. Rotina interna não cria livremente obrigações individuais.'],
['Manifestação do pensamento','Pessoa assina crítica política e pode responder por eventual abuso. Assinale a opção correta.','A manifestação é livre, vedado o anonimato, e são assegurados resposta e reparação quando cabíveis.',['Crítica depende de licença prévia.','Anonimato absoluto é garantido.','Liberdade exclui toda responsabilidade.','Resposta só cabe contra autoridade pública.'],'A Constituição protege manifestação, veda anonimato e assegura resposta proporcional e indenização quando cabíveis. Não há censura prévia geral ou imunidade absoluta.'],
['Inviolabilidade domiciliar','À noite, policiais têm mandado judicial, mas não há consentimento, flagrante, desastre ou socorro. Assinale a opção correta.','Mandado judicial autoriza ingresso durante o dia; à noite valem as exceções constitucionais indicadas.',['Mandado permite ingresso a qualquer hora.','Residência temporária não é protegida.','Conveniente investigação basta à noite.','É necessária autorização do Ministério Público.'],'A Constituição admite ingresso por determinação judicial durante o dia; à noite, apenas nas exceções constitucionais, incluindo consentimento. Conveniência não é exceção.']
]);add('Noções de Direito Constitucional','AG-Q1-CON-',[
['Liberdade de reunião','Cidadãos fazem reunião pacífica, sem armas, avisam previamente e não frustram outra reunião no local. Assinale a opção correta.','A reunião independe de autorização, se atendidos os requisitos constitucionais.',['Exige licença discricionária do prefeito.','Exige ordem judicial.','Aviso prévio equivale a censura.','Pode ser armada para frustrar reunião anterior.'],'A reunião é assegurada sem autorização, desde que pacífica, sem armas, avisada previamente e sem frustrar reunião anterior. Aviso não é licença.'],
['Liberdade de associação','Associação lícita é dissolvida por decisão administrativa sem processo judicial. Assinale a opção correta.','Suspensão e dissolução compulsória dependem de decisão judicial; a dissolução exige trânsito em julgado.',['Portaria administrativa basta.','Suspensão também dispensa Judiciário.','Autorização do MP substitui decisão judicial.','Requerimento de terceiro dissolve associação.'],'A Constituição reserva ao Judiciário suspensão e dissolução, exigindo trânsito em julgado para esta. Administração não dissolve por portaria.'],
['Propriedade e função social','Proprietário sustenta que seu direito é absoluto e imune a limitações constitucionais. Assinale a opção correta.','A propriedade é garantida e deve atender à função social, submetendo-se a limites constitucionais e legais.',['Constituição não protege propriedade privada.','Propriedade afasta regras ambientais.','Função social vale só para bem público.','Desapropriação é sempre vedada.'],'Propriedade é direito constitucional, mas não absoluto: deve cumprir função social e admite limitações e desapropriação nos termos da Constituição.'],
['Devido processo legal','Administração aplica sanção sem procedimento adequado. Assinale a opção correta.','Devido processo, contraditório e ampla defesa são assegurados em processo judicial e administrativo.',['Garantias só incidem após denúncia penal.','Administração sanciona sem defesa em qualquer hipótese.','Contraditório é exclusivo de tribunal superior.','Ampla defesa não cabe no processo administrativo.'],'A Constituição estende essas garantias aos processos administrativos. A forma depende de lei, mas a Administração não pode suprimi-las genericamente.'],
['Habeas corpus','Pessoa sofre ameaça ilegal à liberdade de locomoção. Assinale o remédio constitucional adequado.','O habeas corpus protege a liberdade de locomoção contra ilegalidade ou abuso de poder.',['Mandado de segurança protege toda ameaça à locomoção.','Habeas data substitui ação penal.','Ação popular tutela liberdade física.','Só advogado pode impetrar habeas corpus.'],'Habeas corpus tutela ir, vir e permanecer; não se confunde com dados, patrimônio público ou direito líquido e certo. Pode ser impetrado por qualquer pessoa.'],
['Mandado de segurança','Pessoa quer proteger direito líquido e certo não amparado por HC ou HD diante de ilegalidade de autoridade. Assinale a opção correta.','Em princípio, cabe mandado de segurança, com prova pré-constituída e observância dos requisitos legais.',['Cabe HC sem ameaça à locomoção.','Habeas data tutela qualquer direito patrimonial.','Ação popular é remédio individual para toda ilegalidade.','MS serve a direito que dependa de ampla instrução probatória.'],'O MS tutela direito líquido e certo não coberto por HC ou HD. Exige prova pré-constituída e não substitui os outros remédios.'],
['Habeas data','Cidadã deseja conhecer e corrigir dados pessoais seus em banco de dados governamental. Assinale a opção correta.','Habeas data permite conhecer e retificar dados pessoais nos registros previstos constitucionalmente.',['HC é instrumento específico para cadastro.','Ação popular corrige dados individuais.','HD protege só dados de terceiros.','Mandado de injunção substitui qualquer pedido de dado.'],'Habeas data trata de conhecimento e retificação de dados pessoais em registros públicos ou de caráter público, não de locomoção ou controle popular.'],
['Mandado de injunção','Omissão regulamentadora impede exercício de prerrogativa constitucional. Assinale a opção correta.','Mandado de injunção pode enfrentar falta de norma que inviabilize direito constitucional.',['Habeas data supre qualquer omissão.','MS substitui o processo legislativo.','Omissão torna direito inexistente.','Ação popular é remédio específico para omissão.'],'O MI enfrenta omissão normativa que inviabiliza direito ou prerrogativa constitucional; não elimina o direito nem se confunde com remédios de dados ou locomoção.']
]);add('Noções de Direito Constitucional','AG-Q1-CON-',[
['Federação e autonomia','Projeto transforma município em ente soberano com direito de secessão. Assinale a opção correta.','Municípios são autônomos, mas não soberanos; a Federação é indissolúvel.',['Municípios são soberanos e podem separar-se.','Soberania pertence a cada município.','Secessão cabe por plebiscito local.','Só a União possui autonomia.'],'União, estados, DF e municípios são entes autônomos nos termos constitucionais; soberania é da República e não há direito de secessão.'],
['Competência municipal','Lei municipal disciplina assunto de interesse local e suplementa normas federais e estaduais no que couber. Assinale a opção correta.','A Constituição confere ao município competência sobre interesse local e suplementação legislativa pertinente.',['Municípios não legislam.','Competência local permite contrariar CF.','Suplementação revoga lei federal.','União legisla exclusivamente sobre todo tema local.'],'A competência municipal abrange interesse local e suplementação no que couber, respeitadas Constituição e competências alheias.'],
['Intervenção federal','Cogita-se intervenção federal em estado por hipótese constitucional. Assinale a opção correta.','A intervenção é excepcional e sujeita às hipóteses e procedimentos constitucionais.',['União intervém livremente por conveniência.','Intervenção é supervisão ordinária.','Decreto dispensa requisitos constitucionais.','Autonomia impede qualquer intervenção.'],'Intervenção restringe autonomia e só cabe nos casos e procedimentos constitucionais. Não é poder irrestrito nem incompatível com a própria Constituição.'],
['Princípios da administração','Ato administrativo tem finalidade pessoal embora invocada competência legal. Assinale a opção correta.','Administração observa legalidade, impessoalidade, moralidade, publicidade e eficiência, entre outros princípios.',['Finalidade pessoal é impessoal.','Legalidade torna legítimo qualquer ato imoral.','Art. 37 vincula só União.','Eficiência supera os outros princípios.'],'Os princípios expressos no art. 37 vinculam entes públicos; finalidade pessoal afronta impessoalidade e eficiência não se sobrepõe aos demais.'],
['Concurso público','Pessoa quer cargo efetivo sem concurso, fora da hipótese de cargo em comissão declarado em lei. Assinale a opção correta.','Investidura em cargo ou emprego depende de concurso, ressalvadas hipóteses constitucionais.',['Todo cargo efetivo pode ser indicado.','Concurso vale só para emprego privado.','Concurso dispensa criação legal do cargo.','Administração escolhe sem classificação.'],'Regra constitucional exige concurso para cargo ou emprego, ressalvadas exceções como cargos em comissão legais. A Administração observa requisitos e classificação.'],
['Acumulação de cargos','Servidor acumula dois cargos remunerados sem compatibilidade de horários nem exceção constitucional. Assinale a opção correta.','Acumulação remunerada é vedada como regra e exceções exigem compatibilidade de horários.',['Autorização da chefia sempre basta.','Horários são irrelevantes.','Constituição proíbe inclusive acumulações permitidas.','Regra alcança apenas servidores federais.'],'A Constituição estabelece vedação geral e hipóteses excepcionais condicionadas a compatibilidade. A chefia não cria nova exceção; o regime alcança os entes na forma constitucional.'],
['Estabilidade','Servidor efetivo completa o prazo constitucional e passa por avaliação especial. Assinale a opção correta.','Estabilidade exige cargo efetivo, concurso, três anos de exercício e avaliação especial de desempenho.',['Concurso gera estabilidade antes da posse.','Todo empregado é estável em um ano.','Estabilidade impede perda do cargo em qualquer hipótese.','Estabilidade depende só de decisão da chefia.'],'Art. 41 exige três anos de efetivo exercício e avaliação especial para servidor efetivo concursado; há hipóteses constitucionais de perda do cargo.'],
['Responsabilidade estatal','Agente público causa dano a terceiro nessa qualidade. Assinale a opção correta.','A pessoa jurídica estatal responde objetivamente, com regresso contra agente em caso de dolo ou culpa.',['Vítima deve provar dolo do agente para demandar Estado.','Estado nunca responde.','Responsabilidade objetiva elimina regresso.','Agente responde exclusivamente.'],'O art. 37, §6º, estabelece responsabilidade estatal objetiva e regresso contra agente em caso de dolo ou culpa; os regimes não se confundem.']
]);add('Noções de Direito Constitucional','AG-Q1-CON-',[
['Poder Legislativo','Estudante diz que Legislativo apenas legisla e nunca fiscaliza. Assinale a opção correta.','Legislar e fiscalizar são funções típicas do Legislativo, que também exerce funções atípicas constitucionais.',['Fiscalização cabe exclusivamente ao Judiciário.','Legislativo não administra seus serviços.','Executivo legisla exclusivamente.','Separação proíbe função atípica.'],'Além da produção legislativa, há fiscalização e controle; o Legislativo também administra seus serviços e exerce outras funções constitucionais específicas.'],
['Iniciativa reservada','Projeto sobre matéria de iniciativa reservada é apresentado por parlamentar e aprovado. Assinale a opção correta.','A aprovação não sana necessariamente vício de iniciativa quando a Constituição reserva proposição a autoridade específica.',['Sanção presidencial sempre convalida vício.','Iniciativa reservada não existe.','Todo projeto nasce no Judiciário.','Vício é irrelevante se houver apoio popular.'],'A iniciativa reservada é imposição formal constitucional e sua violação pode invalidar a lei. É necessário identificar a matéria e o dispositivo aplicável.'],
['Poder regulamentar','Executivo edita decreto para detalhar execução de lei, sem exceder seus limites. Assinale a opção correta.','Poder regulamentar viabiliza fiel execução legal e não permite contrariar ou substituir a lei.',['Decreto revoga lei.','Executivo legisla ilimitadamente por decreto.','Decreto contraria lei regulamentada.','Regulamentação é exclusiva do Judiciário.'],'Decreto regulamentar é subordinado à lei e à Constituição. Não pode revogar lei nem inovar indevidamente fora da competência normativa.'],
['Jurisdição e acesso','Órgão executivo quer decisão administrativa com força geral de coisa julgada judicial em controvérsia individual. Assinale a opção correta.','Jurisdição é função típica do Judiciário; lesão ou ameaça a direito não pode ser excluída da apreciação judicial.',['Administração sempre forma coisa julgada judicial.','Constituição veda controle judicial administrativo.','Congresso exerce exclusivamente jurisdição.','Acesso depende de autorização do Executivo.'],'Decisões administrativas têm efeitos próprios, mas não equivalem genericamente à coisa julgada judicial. A Constituição assegura tutela para lesão ou ameaça a direito.'],
['Controle difuso','Juiz deixa de aplicar lei em caso concreto por incompatibilidade constitucional, observadas as regras processuais. Assinale a opção correta.','É hipótese de controle difuso, incidental em caso concreto, distinto do concentrado.',['Só Presidente controla constitucionalidade.','A decisão sempre elimina a lei para todos.','Juiz não pode examinar Constituição.','Controle difuso cabe só ao Tribunal de Contas.'],'O controle difuso permite exame judicial incidental segundo regras como reserva de plenário quando aplicável. Não retira automaticamente a lei do ordenamento para todos.'],
['Ministério Público','Autoridade afirma que Ministério Público integra o Judiciário e deve obedecer a ordens de juízes para propor ação. Assinale a opção correta.','O MP é instituição permanente e essencial à Justiça, com autonomia constitucional, não integrando o Judiciário.',['MP é subordinado ao juiz do processo.','MP integra o Legislativo.','MP defende apenas interesses privados disponíveis.','Constituição não confere autonomia institucional.'],'O MP defende ordem jurídica, regime democrático e interesses sociais e individuais indisponíveis. É função essencial autônoma, não órgão do Judiciário.'],
['Advocacia pública','Estado precisa de representação judicial e consultoria jurídica. Assinale a opção correta.','Essas atribuições cabem à advocacia pública, nos termos constitucionais e legais.',['São exclusivas da Defensoria.','Representação estatal cabe sempre ao MP.','Advocacia pública não presta consultoria.','É função da Polícia Civil.'],'Advocacia pública representa entes e presta consultoria e assessoramento jurídicos, conforme a Constituição. Não se confunde com Defensoria, MP ou polícia.'],
['Defensoria Pública','Pessoa necessitada busca orientação e defesa jurídica integral e gratuita. Assinale a opção correta.','A Defensoria é instituição essencial à Justiça incumbida da orientação e defesa dos necessitados.',['Assistência gratuita cabe só ao MP.','Defensoria atua só em processos criminais.','Representa todos os entes públicos.','Constituição não prevê assistência jurídica.'],'A Defensoria presta orientação e defesa judicial e extrajudicial aos necessitados, integral e gratuitamente, nos termos constitucionais; não é órgão de acusação estatal.']
]);add('Noções de Direito Constitucional','AG-Q1-CON-',[
['Estado de defesa','Presidente considera decretar estado de defesa em locais restritos diante de hipótese constitucional. Assinale a opção correta.','É medida excepcional, decretada nos pressupostos e limites constitucionais, sujeita a controle do Congresso.',['Governador decreta sem previsão constitucional.','Suspende toda a Constituição no país.','É ordinária e sem controle.','Pode ser indefinida e sem local delimitado.'],'Estado de defesa tem pressupostos, delimitação, prazo e controle previstos na Constituição, inclusive atuação do Congresso; não suspende integralmente a ordem.'],
['Estado de sítio','Presidente pretende decretar estado de sítio sem autorização do Congresso por alegada urgência. Assinale a opção correta.','O estado de sítio depende de autorização prévia do Congresso e dos demais requisitos constitucionais.',['Autorização é sempre dispensável.','Decreta o STF.','Urgência transforma-o em ato administrativo comum.','Pode decretá-lo governador.'],'A Constituição exige autorização congressual prévia e pressupostos próprios. Urgência não afasta requisitos constitucionais.'],
['Forças Armadas','Autoridade estadual quer empregar Forças Armadas em atividade policial ordinária por ordem própria. Assinale a opção correta.','Seu emprego obedece à missão constitucional e à legislação federal, não decorrendo de ordem unilateral estadual.',['Forças Armadas subordinam-se a governador.','Qualquer policial requisita emprego irrestrito.','Substituem permanentemente órgãos policiais.','Constituição não define sua missão.'],'As Forças Armadas defendem a Pátria, garantem poderes constitucionais e, por iniciativa constitucional, lei e ordem sob autoridade do Presidente, na forma legal.'],
['Segurança pública: caput','Gestor afirma que segurança pública é apenas dever estatal, sem direito nem responsabilidade de todos. Assinale a opção correta.','É dever do Estado, direito e responsabilidade de todos, voltada à ordem e à incolumidade das pessoas e do patrimônio.',['É responsabilidade exclusiva das Forças Armadas.','É direito apenas de servidores.','Protege somente patrimônio privado.','Responsabilidade coletiva transfere coerção a particulares.'],'O art. 144 combina dever estatal, direito e responsabilidade de todos com finalidades de ordem e proteção. Participação social não transfere poder coercitivo.'],
['Art. 144: órgãos','Alternativa inclui Judiciário e exclui Polícia Federal da lista constitucional de segurança pública. Assinale a opção correta.','A lista abrange PF, PRF, PFF, polícias civis, PMs, corpos de bombeiros militares e polícias penais, conforme o art. 144.',['Judiciário é órgão policial do art. 144.','PF não integra segurança pública.','A Constituição enumera só polícias municipais.','MP substitui todos os órgãos policiais.'],'A Constituição enumera os órgãos indicados. Judiciário e MP têm funções próprias, mas não são órgãos policiais listados nesse artigo.'],
['Polícia Federal','Infração de repercussão interestadual exige repressão uniforme nos termos legais. Assinale a opção correta sobre a PF.','A Constituição prevê atuação da PF nesses casos, quando exigida repressão uniforme, conforme a lei.',['PF investiga só infrações estaduais sem repercussão.','Repercussão exclui competência federal.','PF faz policiamento ostensivo geral municipal.','Atuação da PF independe da lei.'],'A competência constitucional da PF inclui esses casos nos termos legais. Repercussão não cria competência ilimitada nem policiamento geral irrestrito.'],
['Polícia Rodoviária Federal','Candidato diz que PRF patrulha ostensivamente rodovias estaduais como atribuição constitucional principal. Assinale a opção correta.','A PRF destina-se ao patrulhamento ostensivo das rodovias federais, na forma da lei.',['Patrulha ruas municipais exclusivamente.','Exerce polícia judiciária estadual em todos os crimes.','Não há órgão federal rodoviário na Constituição.','Substitui polícias civis nas investigações.'],'O art. 144 atribui à PRF patrulhamento ostensivo de rodovias federais, não policiamento municipal geral ou substituição da PC.'],
['Polícia Civil: CF','Questão atribui à PC policiamento ostensivo e preservação da ordem. Assinale a opção correta.','À PC, dirigida por delegados de carreira, cabem polícia judiciária e apuração de infrações penais, exceto militares, ressalvada competência da União.',['PC exerce exclusivamente policiamento ostensivo.','PC apura toda infração militar.','PC subordina-se ao Judiciário.','PC não exerce polícia judiciária.'],'Art. 144, §4º, prevê direção por delegados de carreira e funções investigativas, com ressalva militar e da União. Ostensividade cabe à PM.']
]);for(const id of ['AG-Q1-CON-002','AG-Q1-CON-008','AG-Q1-CON-009','AG-Q1-CON-015','AG-Q1-CON-031','AG-Q1-CON-032','AG-Q1-CON-043','AG-Q1-CON-046']){const i=bank['Noções de Direito Constitucional'].findIndex(q=>q.id===id);if(i>=0)bank['Noções de Direito Constitucional'].splice(i,1);}})();
